#!ibl edition=2
$t = [self:finance]{op:"query", query_type:"지출", month:"2026-09"}
return $t.items >> [table:sort]{by:"amount", descending:true} >> [table:take]{n:5} >> [table:select]{columns:["date","counterparty","amount"]}

#!ibl edition=2
$g = [self:finance]{op:"query", query_type:"지출", month:"2026-09"} >> [table:groupby]{by:"counterparty", agg:{합계:["sum","amount"], 건수:["count"]}}
return $g.items >> [table:sort]{by:"합계", descending:true} >> [table:take]{n:8}

#!ibl edition=2
$둘 = [self:finance]{op:"query", query_type:"지출", month:"2026-09"} & [self:finance]{op:"query", query_type:"수입", month:"2026-09"}
$합 = $둘 >> [table:each]{ $it >> [table:reduce]{init:0, step:"acc + amount"} }
return {지출:$합[0].value, 수입:$합[1].value, 순지출:$합[0].value - $합[1].value}

#!ibl edition=2
$a = [self:finance]{op:"query", query_type:"지출", month:"2026-08"} >> [table:reduce]{init:0, step:"acc + amount"}
$b = [self:finance]{op:"query", query_type:"지출", month:"2026-09"} >> [table:reduce]{init:0, step:"acc + amount"}
return {전월:$a.value, 이번달:$b.value, 증감률:round(($b.value - $a.value) / $a.value * 100, 1)}

#!ibl edition=2
$w = [self:finance]{op:"query", query_type:"지출", days:90}
$g = $w.items >> [table:compute]{set:($r)=>{월:$r.date[0:7]}} >> [table:groupby]{by:"월", agg:{합계:["sum","amount"]}}
return $g.items >> [table:sort]{by:"월"}

#!ibl edition=2
$s = [self:finance]{op:"query", query_type:"지출", month:"2026-09"} >> [table:reduce]{init:0, step:"acc + amount"}
[if: $s.value > 1000000] { return f"예산 초과: ${$s.value - 1000000}원" } [else] { return f"남은 예산 ${1000000 - $s.value}원" }

#!ibl edition=2
$s = [self:finance]{op:"query", query_type:"지출", month:"2026-09"} >> [table:reduce]{init:0, step:"acc + amount"}
[if: $s.value > 1000000] { [self:notify_user]{message: f"이달 예산 초과: ${$s.value}원"} }

#!ibl edition=2
$t = [self:finance]{op:"query", query_type:"지출", month:"2026-09", category:"식비"}
$c = $t.items >> [table:each]{ $it.category }
return {n:len($t.items), total:$t.total, cats:unique($c)}

#!ibl edition=2
$t = [self:finance]{op:"query", month:"2026-09", category:"식비"}
return {n:len($t.items), msg:get($t,"message",""), text:get($t,"text","")}

#!ibl edition=2
$t = [self:finance]{op:"query", query_type:"지출", month:"2026-09", days:7}
$d = $t.items >> [table:each]{ $it.date }
return {n:len($t.items), oldest:sorted($d)[0]}

#!ibl edition=2
$예산 = [self:ledger]{op:"select", path:"~workspace/outputs/IT72_budget.json", target:"budgets"}
$쓴돈 = [self:finance]{op:"query", query_type:"지출", month:"2026-09"} >> [table:groupby]{by:"source", agg:{사용:["sum","amount"]}}
$쓴 = $쓴돈.items >> [table:compute]{set:($r)=>{category:$r.source}}
$j = [table:join]{left:$쓴, right:$예산.items, on:"category"}
return $j.items >> [table:compute]{set:($r)=>{초과:$r.사용 - $r.budget}} >> [table:filter]{where:($r)=>$r.초과 > 0} >> [table:select]{columns:["source","사용","budget","초과"]}

#!ibl edition=2
$t = [self:finance]{op:"query", query_type:"지출", month:"2026-09"}
$행 = $t.items >> [table:filter]{where:($r)=>$r.amount > 0} >> [table:select]{columns:["counterparty","summary","amount"]}
$판 = $행 >> [table:judge]{instruction:"이 결제의 소비 분류는?", type:"choice", criteria:{식비:"식당·음식점·배달", 카페간식:"카페·빵집·과일·편의점 간식", 통신구독:"통신요금·구독·앱스토어·클라우드", 의료:"병원·약국", 기타:"그 밖이나 판단 불가"}}
$g = $판.items >> [table:compute]{set:($r)=>{category:get($r,"judgment_result_value","미판정")}} >> [table:groupby]{by:"category", agg:{사용:["sum","amount"]}}
$예산 = [self:ledger]{op:"select", path:"~workspace/outputs/IT72_budget.json", target:"budgets"}
$j = [table:join]{left:$g.items, right:$예산.items, on:"category"}
return {분류:$g.items, 초과:$j.items >> [table:filter]{where:($r)=>$r.사용 > $r.budget}}

#!ibl edition=2
$t = [self:finance]{op:"query", query_type:"지출", month:"2026-09"}
$neg = $t.items >> [table:filter]{where:($r)=>$r.amount < 0} >> [table:compute]{set:($r)=>{금액:abs($r.amount)}}
$pos = $t.items >> [table:filter]{where:($r)=>$r.amount > 0} >> [table:compute]{set:($r)=>{금액:$r.amount}}
$j = [table:join]{left:$neg, right:$pos, on:"금액", how:"left"}
return $j.items >> [table:select]{columns:["date","금액","date_2","record_id_2"]}

#!ibl edition=2
$s = [self:finance]{op:"query", query_type:"지출", month:"2026-01"} >> [table:reduce]{init:0, step:"acc + amount"}
[if: $s.value == 0] { return "지출 없음" } [else] { return f"${$s.value}원" }

#!ibl edition=2
$e = [self:finance]{op:"query", query_type:"지출", month:"2026-09"} >> [table:reduce]{init:0, step:"acc + amount"}
$in = [self:finance]{op:"query", query_type:"수입", month:"2026-09"} >> [table:reduce]{init:0, step:"acc + amount"}
[self:ledger]{op:"upsert", path:"~workspace/outputs/IT72_closing.json", target:"months", key:"month", item:{month:"2026-09", 지출:$e.value, 수입:$in.value, 순액:$in.value - $e.value}, max_items:12}

#!ibl edition=2
$s = [self:finance]{op:"query", query_type:"summary", month:"2026-09"}
return $s.items >> [table:sort]{by:"amount", descending:true} >> [table:take]{n:3}

#!ibl edition=2
$t = [self:finance]{op:"query", query_type:"지출", month:"2026-09"}
return $t.items >> [table:filter]{where:($r)=>$r.amount > 300000} >> [table:select]{columns:["record_id","date","counterparty","amount","source","summary"]}
